if ($_SERVER['REQUEST_METHOD']==='POST') { csrf_validar(); $u=trim($_POST['usuario']??'');$p=(string)($_POST['contrasena']??'');
 $q=$pdo->prepare('SELECT u.*,r.nombre_rol FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol WHERE u.usuario=? LIMIT 1');$q->execute([$u]);$row=$q->fetch();
 if($row && $row['activo'] && (!$row['bloqueado_hasta'] || strtotime($row['bloqueado_hasta'])<time()) && password_verify($p,$row['password_hash'])) { session_regenerate_id(true);$_SESSION['id_usuario']=$row['id_usuario'];$_SESSION['nombre_completo']=$row['nombre_completo'];$_SESSION['rol']=$row['nombre_rol'];$_SESSION['ultima_actividad']=time();$pdo->prepare('UPDATE usuarios SET intentos_fallidos=0,bloqueado_hasta=NULL,ultimo_acceso=NOW() WHERE id_usuario=?')->execute([$row['id_usuario']]);header('Location: modulos/camas/');exit; }
 if($row){$fallos=(int)$row['intentos_fallidos']+1;$bloqueo=$fallos>=5?date('Y-m-d H:i:s',time()+300):null;$pdo->prepare('UPDATE usuarios SET intentos_fallidos=?,bloqueado_hasta=? WHERE id_usuario=?')->execute([$fallos,$bloqueo,$row['id_usuario']]);}
 $error='Usuario o contraseña incorrectos, o cuenta temporalmente bloqueada.';
}
